UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
    utf8proc_ssize_t rpos;
    utf8proc_ssize_t wpos = 0;
    utf8proc_int32_t uc;
    for (rpos = 0; rpos < length; rpos++) {
      uc = buffer[rpos];
      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
        if (options & UTF8PROC_NLF2LS) {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x000A;
          } else {
            buffer[wpos++] = 0x2028;
          }
        } else {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x2029;
          } else {
            buffer[wpos++] = 0x0020;
          }
        }
      } else if ((options & UTF8PROC_STRIPCC) &&
          (uc < 0x0020 || (uc >= 0x007F && uc < 0x00A0))) {
        if (uc == 0x0009) buffer[wpos++] = 0x0020;
      } else {
        buffer[wpos++] = uc;
      }
    }
    length = wpos;
  }

UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
    utf8proc_ssize_t rpos;
    utf8proc_ssize_t wpos = 0;
    utf8proc_int32_t uc;
    for (rpos = 0; rpos < length; rpos++) {
      uc = buffer[rpos];
      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
        if (options & UTF8PROC_NLF2LS) {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x000A;
          } else {
            buffer[wpos++] = 0x2028;
          }
        } else {
          if (options & UTF8PROC_NLF2PS) {
            buffer[wpos++] = 0x2029;
          } else {
            buffer[wpos++] = 0x0020;
          }
        }
      } else if ((options & UTF8PROC_STRIPCC) &&
          /* uc < 0 is a grapheme-break sentinel from UTF8PROC_CHARBOUND,
             not a control character, so keep it */
          ((uc >= 0 && uc < 0x0020) || (uc >= 0x007F && uc < 0x00A0))) {
        if (uc == 0x0009) buffer[wpos++] = 0x0020;
        /* a removed control character is a grapheme of its own, so also
           drop the boundary sentinel that UTF8PROC_CHARBOUND put before it */
        else if ((options & UTF8PROC_CHARBOUND) && wpos > 0 && buffer[wpos-1] == -1) wpos--;
      } else {
        buffer[wpos++] = uc;
      }
    }
    length = wpos;
  }

utf8proc_int32_t *copy = size >= 4 ? malloc(size) : NULL;

if(copy)
{
    size /= 4; /* number of utf8proc_int32_t code points that fit in copy */

    options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_STRIPCC | UTF8PROC_NLF2PS;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_STRIPCC;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = UTF8PROC_LUMP;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    options = 0;
    memcpy(copy, data, size * sizeof(utf8proc_int32_t));
    utf8proc_normalize_utf32(copy, size, options);

    free(copy);
}

utf8proc_free(utf8proc_NFD(data));
utf8proc_free(utf8proc_NFC(data));
utf8proc_free(utf8proc_NFKD(data));
utf8proc_free(utf8proc_NFKC(data));
utf8proc_free(utf8proc_NFKC_Casefold(data));

utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_STRIPNA);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_LUMP | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_COMPOSE | UTF8PROC_STRIPMARK);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_DECOMPOSE);
utf8proc_free(str);

utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_COMPOSE);
utf8proc_free(str);
